    79→import moment from 'moment';
    80→
    81→export default {
    82→  props: {
    83→    documentName: {
    84→      type: String,
    85→      required: true,
    86→    },
    87→    document: {
    88→      type: Object,
    89→      required: true,
    90→    },
    91→    fields: {
    92→      type: Array,
    93→      required: true,
    94→    },
    95→    allFields: {
    96→      type: Array,
