filteredAllFieldsForTemplate() {
    const allFields = [];
    for (const pdfId in this.allPdfFields) {
        const fields = this.allPdfFields[pdfId] || [];
        const filtered = fields.filter(field => {
            const signerCorresponds = this.documentPackages.some(pkg =>
                pkg.signers.some(signer => signer.signers_order == field.id)
            );
            return !signerCorresponds;
        });
        filtered.forEach(field => {
            allFields.push({
                ...field,
                pdfId: parseInt(pdfId)
            });
        });
    }
    return allFields;
},

