async function getDefaultSigners(req, res) {
    try {
        const document_package_header_id = parseInt(req.body.packageID);

        const groupSigners = await db.documents_group_signers.findMany({
            where: {
                document_package_header_id: document_package_header_id
            },
            include: {
                user: { 
                    include: {
                        company: true, 
                        doc_type: true 
                    }
                }
            }
        });

        if (groupSigners.length === 0) {
            return res.status(404).send({
                status: false,
                message: `No se encontraron firmantes para el paquete`,
            });
        }

        const data = groupSigners.map(gs => {
            const { user } = gs;
            return {
                id: user.id,
                firstname: user.firstname,
                lastname: user.lastname,
                email: user.email,
                id_number: user.id_number,
                full_name: `${user.firstname} ${user.lastname}`,
                id_type: user.doc_type.name,  // Nombre del tipo de documento
                document_type: user.id_type,   // ID del tipo de documento
                order: gs.order,
                phone: user.phone,
                phone_code: user.phone_code || 57,
                company_id: user.company_id,
                fiscal_name: user.company?.fiscal_name,
                company_name: user.company?.company_name,
                company_api_key: user.company?.api_key,
                avatar: user.avatar_picture,
                role_id: user.role_id,
                admin_sign: user.admin_sign,
                company_sign_default: user.company_sign_default,
            };
        });

        return res.status(200).send({
            status: true,
            data,
        });

    } catch (e) {
        console.error("Error en getDefaultSigners:", e);
        return res.status(500).send({
            status: false,
            message: `Error en el servidor: ${e.message}`,
        });
    }
}
```

