async function sendSolicitudesFirmaSequential(id, document_signers, company, valid_at_date, valid_at_hour, currentUserId, packageName) {
    for (let i = 0; i < document_signers.length; i++) {
        const signer = document_signers[i];

        if (await hasSigned(signer)) {
            console.log(`El firmante ${signer.user_id} ya ha firmado, no se envía solicitud de nuevo.`);
            continue; 
        }

        if (parseInt(signer.user_id) === parseInt(currentUserId)) {
            console.log(`El firmante actual ${signer.user_id} no recibirá la solicitud de nuevo.`);
            continue; 
        }

        const user = await db.users.findFirst({
            where: { id: parseInt(signer.user_id) },
            select: {
                id: true,
                firstname: true,
                lastname: true,
                email: true,
            },
        });

        const _url = process.env.ENV_URL + signer.token;

        if (i === 0 || await hasSigned(document_signers[i - 1])) {
            await service.sendSolicitudFirma(
                user.email,
                company.avatar,
                `${user.firstname} ${user.lastname}`,
                company.fiscal_name,
                company.fiscal_name,
                company.fiscal_name,
                valid_at_date,
                valid_at_hour,
                _url,
                company.company_email,
                packageName,
                company.advanced_settings || '',
                currentUserId,
                id,
                company.id
            );

            break; 
        } else {
            console.log(`El firmante anterior aún no ha firmado. No se envía solicitud a: ${user.email}`);
        }
    }
}

