async function processDocuments(documentPackageSigner, user, signImageBase64, ip, fieldsValues) {
    const s3Keys = documentPackageSigner.documents.map(d => d.s3_key);
    const ids = documentPackageSigner.documents.map(d => d.id);
    const contentsFromS3 = await service.getContentFromS3(ids, s3Keys);
    const htmlDocuments = [];
    const private_key = fs.readFileSync("./my_key.key", "utf-8");

    for (const doc of documentPackageSigner.documents) {
        let htmlContent = contentsFromS3[doc.id];

        const userSignatureHtml = createSignatureBlock(user, signImageBase64);
        htmlContent = await findReplaceString(htmlContent, documentPackageSigner.signers[0].order, userSignatureHtml);

        htmlContent = await handleDefaultSigners(htmlContent, documentPackageSigner, ip);

        if (fieldsValues && fieldsValues.length > 0) {
            const result = await updateContentWithFields(
                htmlContent,
                fieldsValues,
            );

            if (result.success) {
                htmlContent = result.updatedContent; 
            } else {
                console.error("Failed to update content:", result.error);
            }
        }

        const modifiedToken = jwt.sign({ pdf: htmlContent }, private_key, { algorithm: "RS512" });
        await uploadToS3(doc.s3_key, modifiedToken, 'application/jwt');

        const templateDetails = doc.document_packages_details?.template;

        if (templateDetails) {
            htmlDocuments.push({
                htmlContent: htmlContent,
                id: doc.id,
                name: doc.name,
                header: templateDetails.header_content,
                footer: templateDetails.footer_content,
                paperSize: templateDetails.paper_size,
                customWidth: templateDetails.custom_width,
                customHeight: templateDetails.custom_height,
             });
        }
    }
    return htmlDocuments;
}

function createSignatureBlock(user, signImage) {
    return `
      <div class="new-signature" style="display: flex; flex-direction: column; align-items: left; width: 100%; height: auto; border: 1px solid transparent;box-sizing: border-box;">
          <div style="display: flex; align-items: center; gap: 5px; width: 100%;">
              <spans tyle="font-size: 12px; font-family: Arial, sans-serif; word-wrap: break-word;">Firmado digitalmente a través de Quality Sign</spans>
              <img src="https://publicofirmadigital.s3.amazonaws.com/assets/img/templates/vertical_logo_qs.png" style="max-height: 50px; max-width: 50px; opacity: 0.7; margin-top: 5px;"  />
          </div>
          <img src="${signImage}" style="max-height:80px; width:150px" />
          <div class="new-modified_content">
              <p><span class="name">${user.firstname} ${user.lastname}</span></p>
              <p><span class="document">${user.doc_type.abbreviation}: ${user.id_number}</span></p>
          </div>
      </div>
    `;
}

async function handleDefaultSigners(htmlContent, documentPackageSigner, ip) {

    if (documentPackageSigner.document_packages_header.has_signers !== 1) {
        return htmlContent;
    }

    let updatedHtml = htmlContent;
    const defaultSigners = documentPackageSigner.document_packages_header.group_signers
        .filter(gs => gs.is_default_sign === 1 && gs.days_to_sign === 0);

    if (defaultSigners.length === 0) {
        return updatedHtml;
    }

    for (const defaultSigner of defaultSigners) {
        const defaultUserData = await db.users.findFirst({
            where: { id: parseInt(defaultSigner.user_id) },
            select: { id: true, admin_sign: true, firstname: true, lastname: true, id_number: true, doc_type: { select: { abbreviation: true } } },
        });

        if (defaultUserData && defaultUserData.admin_sign) {
            const signatureHtml = createSignatureBlock(defaultUserData, defaultUserData.admin_sign);
            updatedHtml = await findReplaceString(updatedHtml, defaultSigner.order, signatureHtml);

            const signUrlDefault = await service.uploadSignToS3(documentPackageSigner.company_id, documentPackageSigner.id, defaultUserData.admin_sign);
            await db.document_signers.updateMany({
                where: {
                    document_package_signer_id: documentPackageSigner.id,
                    user_id: defaultUserData.id,
                },
                data: {
                    status: "accepted",
                    signed_at: new Date(),
                    ip_address: getServerIp(),
                    sign_url: signUrlDefault,
                    updated_at: new Date(),
                },
            });
        }
    }
    return updatedHtml;
}

