async function updateHashDocumentSigned(documentPackageSignerId) {
    try {
        const documentPackageSigner = await db.document_packages_signers.findFirst({
            where: {
                id: parseInt(documentPackageSignerId),
            },

            select: {
                id: true,
                signers: {
                    select: {
                       sign: true
                    },

                },
                documents: {
                    select: {
                        id: true,
                        name: true,
                        s3_key: true,

                    }
                },
            }

        });

        const signers = documentPackageSigner.signers;
        const documents = documentPackageSigner.documents;

        const allSignatures = signers.map(signer => signer.sign).join('-');

        for (const document of documents) {
            const documentString = `${document.id}-${allSignatures}-${documentPackageSignerId}`;

            const documentHash = crypto.createHash('sha256').update(documentString).digest('hex');

            await db.document_packages_signers_details_values.updateMany({
                where: {
                    id: document.id,
                    document_package_signer_id: parseInt(documentPackageSignerId),
                },
                data: {
                    document_hash: documentHash,
                },
            });

        }

        return true;

    } catch (error) {
        console.error("Error al actualizar el estado de firmado:", error);
        return false;
    }

}

async function updateContentWithFields(
    modified_content,
    fieldsValues
) {

    try {
        if (modified_content) {
            let content = modified_content;

            for (const fieldValue of fieldsValues) {
                const { name, value } = fieldValue;

                const fieldRegex = new RegExp("\\$\\[\\[" + name + "\\]\\]", "g");

                content = content.replace(fieldRegex, value !== undefined && value !== null ? value : `$[[${name}]]`);
            }

            return { success: true, updatedContent: content };
        } else {
            throw new Error("Document package detail not found");
        }
    } catch (err) {
        console.error("Error updating content:", err);
        return { success: false, error: err.message };
    }
}

