async function doSignRequestMultiple(req, res) {
    try {

        const [user, company] = await Promise.all([
            db.users.findFirst({
                where: { id: parseInt(req.body.user_id) },
                include: { doc_type: true },
            }),
            db.companies.findFirst({
                where: { id: parseInt(req.body.company_id) },
            })
        ]);

        if (!user.admin_sign) {
            return res.status(400).send({ message: "Por favor, configure su firma digital." });
        }

        const itemsToProcess = [];
        const itemsRemoved = [];
        const processedIdsSet = new Set(); 

        req.body.items.forEach(item => {
            if (item.user_id === parseInt(user.id)) {
                itemsToProcess.push(item);
                processedIdsSet.add(item.id); 
            }
        });

        req.body.items.forEach(item => {
            if (item.user_id !== parseInt(user.id) && !processedIdsSet.has(item.id)) {
                itemsRemoved.push(item);
            }
        });

        if (itemsToProcess.length === 0) {
            return res.status(200).send({ message: "No hay solicitudes para firmar para el usuario actual." });
        }

        const processedIds = [];
        const failedIds = [];

        for (const item of itemsToProcess) {
            try {
                await processSingleItemForMultipleSign(item, user, company, req.ip);
                processedIds.push(item.id);
            } catch (error) {
                console.error(`Error procesando el item ID ${item.id}:`, error);
                failedIds.push(item.id);
            }
        }

        return res.status(200).send({
            status: true,
            message: `Proceso completado. Firmados: ${processedIds.length}. Fallidos: ${failedIds.length}.`,
            items_signed: processedIds.join(", "),
            items_failed: failedIds.join(", "),
            itemsRemoved: [...new Set(itemsRemoved.map(item => item.id))].join(", ")
        });

    } catch (err) {
