}

async function processPdfsWithLambda(documentPackageSigner, signImage, userOrder) {
    const signedDocuments = [];

    const logoBase64 = await fetchImageAsBase64('https://publicofirmadigital.s3.amazonaws.com/assets/img/templates/vertical_logo_qs.png');

    for (const document of documentPackageSigner.documents) {
        const fields = JSON.parse(document.fields || '[]');

        const specificField = fields.filter(field => {
            const fieldNameMatch = field.name.match(/\[\$FIRMA(\d+)\]/);
            return fieldNameMatch && parseInt(fieldNameMatch[1]) === userOrder;
        });

        const lambdaPayload = {
            pdf_url: buildS3Url(document.s3_key),
            sign_image: addBase64Padding(signImage),
            fields: specificField,
            url: document.s3_key,
            logo_image: addBase64Padding(logoBase64),
            index: userOrder,
            folder: process.env.S3_FOLDER,
            bucket: process.env.S3_BUCKET_PREFIX,
        };

        const command = new InvokeCommand({
            FunctionName: 'updatePdfContentTest',
            Payload: JSON.stringify(lambdaPayload),
        });
        const response = await lambdaClient.send(command);
        const resultPayload = JSON.parse(new TextDecoder().decode(response.Payload));


        if (resultPayload.statusCode !== 200) {
            console.error("Error en Lambda al firmar el documento:", resultPayload);
        }

        signedDocuments.push({ name: document.name, key: document.s3_key, id: document.id });
    }

    return signedDocuments;
}

async function fetchImageAsBase64(url) {
    const response = await axios.get(url, { responseType: 'arraybuffer' });
    const base64Image = Buffer.from(response.data, 'binary').toString('base64');
    return base64Image;
}

function buildS3Url(key) {
  const bucket = process.env.S3_BUCKET_PREFIX;
  const folder = process.env.S3_FOLDER;

  let path = key;

  if (folder && folder.trim() !== '') {
    const encodedFolder = encodeURIComponent(folder);
    path = `${encodedFolder}/${key}`;
  }

  return `https://${bucket}.s3.amazonaws.com/${path}`;
}

function addBase64Padding(base64String) {
    return base64String + '='.repeat((4 - base64String.length % 4) % 4);
}

async function checkAndFinalizePdfPackage(tokenPayload, documentPackageSigner, signers, signedDocuments) {
    const statusRequest = await db.document_signers.findMany({
        where: { document_package_signer_id: parseInt(tokenPayload.document_package_signer_id) },
        select: { status: true }
    });

    const allAccepted = statusRequest.every(record => record.status === "accepted");

    if (allAccepted) {

        const packageConsumed = await manageCompanyPackageUnits(
            documentPackageSigner.company.id,
            documentPackageSigner.id
        );

        const updatedPackage = await db.document_packages_signers.update({
            where: { id: parseInt(tokenPayload.document_package_signer_id) },
            data: { status: 'accepted', signed_at: new Date(), processing_status: packageConsumed ? 1 : 0, updated_at: new Date() },
        });

        const signedPdfBuffers = await getSignedPdfBuffersFromS3(signedDocuments);
        const documentHashes = await getDocumentHashes(documentPackageSigner.documents);
        setImmediate(() => updateHashDocumentSigned(tokenPayload.document_package_signer_id).catch(console.error));

        if (packageConsumed) {

            await sendCompletionNotificationsWithAttachments(
                documentPackageSigner,
                signers,
                updatedPackage,
                signedPdfBuffers,
                documentHashes,
                documentPackageSigner.package_name
            );

        }
    }
}

async function sendCompletionNotificationsWithAttachments(documentPackageSigner, signers, updatedPackage, signedPdfBuffers, documentHashes, packageName) {
    const company = documentPackageSigner.company;

    const date = new Date(updatedPackage.updated_at).toLocaleDateString('es-CO');
    const time = new Date(updatedPackage.updated_at).toLocaleTimeString('es-CO');

    for (const signer of signers) {
        const user = await db.users.findUnique({ where: { id: signer.user_id } });
        if (user) {
            const token = service.generate(15); 
            await db.document_viewer.create({
                data: {
                    user_id: user.id,
                    document_package_signer_id: documentPackageSigner.id,
                    token: token,
                },
            });

            await service.sendSignedDocumentsNotification(
                user.email,
                `${user.firstname} ${user.lastname}`,
                company.avatar,
                company.fiscal_name,
                token,
                date,
                time,
                process.env.URL_DOCUMENTS,
                company.email,
                packageName ? packageName : documentPackageSigner.documents[0].name,
                signedPdfBuffers, 
            );
        }
    }

    if (documentPackageSigner.recipients.length > 0) {
        const groupEmails = documentPackageSigner.recipients.map(r => r.email);
        if (groupEmails.length > 0) {
            await service.sendGroupEmails(
                groupEmails,
                documentPackageSigner.id,
                updatedPackage.updated_at,
                documentPackageSigner.documents[0].name,
                company.email,
                true,
                signedPdfBuffers, 
                documentHashes,
            );
        }
    }
}

async function getSignedPdfBuffersFromS3(signedDocuments) {
    return Promise.all(signedDocuments.map(async (doc) => {
        const s3Params = { Bucket: process.env.S3_BUCKET, Key: doc.key };
        const data = await s3Client.send(new GetObjectCommand(s3Params));
        return { name: doc.name, buffer: await data.Body.transformToByteArray() };
    }));
}

async function getDocumentHashes(documents) {
    const hashes = await Promise.all(documents.map(doc =>
        db.document_packages_signers_details_values.findFirst({
            where: { id: parseInt(doc.id) },
            select: { document_hash: true }
        })
    ));
    return documents.map((doc, index) => ({
        name: doc.name,
        hash: hashes[index]?.document_hash || null,
    }));
}

async function signPdfMultiple(req, res) {
    try {

        const user = await db.users.findUnique({
            where: {
                id: parseInt(req.body.user_id)
            }
        });
        if (!user || !user.admin_sign) {
            return res.status(400).send({
                message: "Usuario no encontrado o sin firma digital configurada."
            });
        }

        const itemsToProcess = [];
        const itemsRemoved = [];
        const processedIdsSet = new Set();

        req.body.items.forEach(item => {
            if (item.user_id === parseInt(user.id)) {
                itemsToProcess.push(item);
                processedIdsSet.add(item.id);
            }
        });
        req.body.items.forEach(item => {
            if (item.user_id !== parseInt(user.id) && !processedIdsSet.has(item.id)) {
                itemsRemoved.push(item);
            }
        });

        const successResults = [];
        const failedResults = [];

        for (const item of itemsToProcess) {
            try {
                const result = await processSinglePdfItem(item, user, req.ip);
                successResults.push(result);
            } catch (error) {
                console.error(`Error procesando el paquete de PDF ID ${item.id}:`, error);
                failedResults.push({
                    id: item.id,
                    reason: error.message
                });
            }
        }

        return res.status(200).send({
            status: true,
            message: "Proceso de firma masiva de PDFs finalizado.",
            signed_packages: successResults,
            failed_documents: failedResults,
            removed_packages: itemsRemoved.map(item => item.id),
        });

    } catch (error) {
        console.error("Error en la firma masiva de PDFs:", error);
        res.status(500).json({ status: false, message: "Error en la firma masiva de PDFs" });
    }
}

async function processSinglePdfItem(item, user, ip) {


    const documentPackageSigner = await db.document_packages_signers.findUnique({
        where: {
            id: parseInt(item.id)
        },
        include: { 
            company: true,
            documents: true,
            signers: true,
            recipients: true,
            document_packages_header: {
                include: {
                    group_recipients: true
                }
            },
        }
    });

    if (!documentPackageSigner) {
        throw new Error(`Paquete con ID ${item.id} no encontrado.`);
    }

    const userSigner = documentPackageSigner.signers.find(s => s.user_id === user.id);
    if (!userSigner) {
        throw new Error(`El usuario ${user.id} no es un firmante válido para el paquete ${item.id}.`);
    }

    const signedDocuments = await processPdfsWithLambda(
        documentPackageSigner,
        user.admin_sign, 
        userSigner.order
    );

    const signUrl = await service.uploadSignToS3(documentPackageSigner.company_id, item.id, user.admin_sign);

    const mockTokenPayload = {
        document_package_signer_id: item.id,
        id: user.id
    };
    const mockReq = {
        ip,
        body: {}
    };

    await updateSignerStatusAndLog(mockTokenPayload, mockReq, signUrl);

    const signedAt = new Date();
    const options = { timeZone: 'America/Bogota' };

    service.sendAgradecimientoSolicitudFirma(
        user.email,
        documentPackageSigner.company.avatar,
        `${user.firstname} ${user.lastname}`,
        documentPackageSigner.company.fiscal_name,
        signedAt.toLocaleDateString('es-CO', options),
        signedAt.toLocaleTimeString('es-CO', options),
        documentPackageSigner.company.email
    );

    await checkAndFinalizePdfPackage(mockTokenPayload, documentPackageSigner, documentPackageSigner.signers, signedDocuments);

    return {
        id: item.id,
        documents: signedDocuments.map(d => d.name)
    };
}

