                            company.fiscal_name,
                            company.fiscal_name,
                            company.fiscal_name,
                            date,
                            time,
                            _url,
                            company.email,
                            request.document_packages_header.name,
                            advancedSettings[0].email_message || "",
                            user.id,
                            request.id,
                            company.id
                        );
                        status = true;
                        break; 
                    }
                }
            } else {
                for (const signer of sortedSigners) {
                    if (signer.status === "send" || signer.status === "rejected") {
                        const user = users.find(u => u.id === signer.user_id);
                        const _url = process.env.ENV_URL + signer.token;

                        await service.sendSolicitudFirma(
                            user.email,
                            company.avatar,
                            `${user.firstname} ${user.lastname}`,
                            company.fiscal_name,
                            company.fiscal_name,
                            company.fiscal_name,
                            date,
                            time,
                            _url,
                            company.email,
                            request.document_packages_header.name,
                            company.advanced_settings[0].email_message || "",
                            user.id,
                            request.id,
                            company.id
                        );
                        status = true;
                    }
                }
            }

            if (status) {
                message = "La solicitud ha sido reenviada";

                await db.document_packages_signers_logs.create({
                    data: {
                        document_package_signer_id: parseInt(request.id),
                        event_description: "La solicitud ha sido reenviada",
                        performed_by_user_id: parseInt(req.body.user_id_creator),
