async function findReplaceString(html, signer_order, replace) {
    const $ = cheerio.load(html);
    const searchString = `[$FIRMA${signer_order}]`;

    $("div.new-signature").each(function () {
        const $this = $(this);
        const divContent = $this.html();

        if (divContent.includes(searchString)) {
            const next = $this.next();

            if (next.hasClass("new-modified_content") || next.find(".new-modified_content").length > 0) {
                next.remove();
            }

            $this.replaceWith(replace);
        }
    });

    return $.html();
}

