async function checkAndFinalizePackage(tokenPayload, documentPackageSigner, date, time, htmlDocs) {
    const signersStatus = await db.document_signers.findMany({
        where: { document_package_signer_id: parseInt(tokenPayload.document_package_signer_id) },
        select: { status: true, order: true },
    });

    const allAccepted = signersStatus.every(s => s.status === "accepted");

    const signerOrder2Accepted = signersStatus.some(s => s.order === 2 && s.status === "accepted");
    if (signerOrder2Accepted && !allAccepted && documentPackageSigner.from_api === 1) {
        await notifyExternalAPI(documentPackageSigner, "employee_signed");
    }

    if (allAccepted) {
        await completeSigningProcess(tokenPayload, documentPackageSigner, date, time, htmlDocs);
    }
}

async function completeSigningProcess(tokenPayload, documentPackageSigner, date, time, htmlDocs) {

    const packageConsumed = await manageCompanyPackageUnits(documentPackageSigner.company.id, documentPackageSigner.id);
    const now = new Date();

    const updateResult = await db.document_packages_signers.update({
        where: { id: parseInt(tokenPayload.document_package_signer_id), processing_status: { not: 1 } },
        data: { status: 'accepted', signed_at: now, updated_at: now, processing_status: packageConsumed ? 1 : 0 },
    });

    if (updateResult.count === 0) {
        console.log(`[IDEMPOTENCIA] La solicitud ${tokenPayload.document_package_signer_id} ya fue procesada.`);
        return;
    }

    await updateHashDocumentSigned(tokenPayload.document_package_signer_id);

    if (packageConsumed) {
        if (documentPackageSigner.from_api === 1) {

            await notifyExternalAPI(documentPackageSigner, "accepted", null);

            generateAndSubmitFinalPDF(documentPackageSigner, updateResult.signed_at, htmlDocs)
                .then(() => {
                    console.log(`PDF generado en segundo plano para ID: ${documentPackageSigner.id}`);
                })
                .catch(error => {
                    console.error(`ERROR CRÍTICO generando PDF en background (ID: ${documentPackageSigner.id}):`, error);
                });
        }
        await sendCompletionNotifications(documentPackageSigner, date, time);
    } else {
        await db.document_packages_signers.update({
            where: { id: documentPackageSigner.id },
            data: { processing_status: 0, updated_at: new Date() }
        });
    }
}

async function manageCompanyPackageUnits(companyId, documentPackageSignerId) {
    let finalCompanyId = companyId;
    const branch = await db.companies.findFirst({
        where: { id: parseInt(companyId), company_parent_id: { not: null } },
        select: { company_parent_id: true },
    });

    if (branch) {
        finalCompanyId = branch.company_parent_id;
    }

    const allPackages = await db.company_packages_assignments.findMany({
        where: {
            company_id: parseInt(finalCompanyId),
            status: 1,
        },
    });

    let selectedPackage = null;
    for (const pkg of allPackages) {
        let isExpired = false;
        const now = new Date();
        const expirationDate = pkg.expiration_date ? new Date(pkg.expiration_date) : null;
        const endDate = pkg.end_date ? new Date(pkg.end_date) : null;

        if ((expirationDate && expirationDate < now) || (endDate && endDate < now)) {
            isExpired = true;
        }

        if (!isExpired) {
            if (Number(pkg.package_id) === 1 && Number(pkg.remaining_units) > 0) {
                selectedPackage = pkg;
                break; 
            }
            else if (Number(pkg.package_id) === 2 && !selectedPackage) {
                selectedPackage = pkg;
            }
        }
    }

    if (selectedPackage) {

        await db.package_transactions.create({
            data: {
                company_packages_assignment_id: parseInt(selectedPackage.id),
                document_package_signer_id: parseInt(documentPackageSignerId),
                user_id: 1,
                quantity: -1,
                created_at: new Date(),
            },
        });

        if (parseInt(selectedPackage.package_id) === 1) {
            await db.company_packages_assignments.update({
                where: { id: parseInt(selectedPackage.id) },
                data: {
                    remaining_units: {
                        decrement: 1,
                    },
                },
            });
        }

        return true; 
    }

    return false; 
}

