async function uploadToS3(key, body, contentType) {
    const params = {
        Bucket: process.env.S3_BUCKET,
        Key: key,
        Body: body,
        ContentType: contentType,
    };
    try {
        const command = new PutObjectCommand(params);
        await s3Client.send(command);
    } catch (error) {
        console.error(`Error al subir el archivo ${key} a S3:`, error);
        throw error; 
    }
}

async function doSignRequest(req, res) {

    try {

        const tokenPayload = jwt.verify(req.body.token, config.SECRET_TOKEN);
        const { documentPackageSigner, signers, user } = await getPackageAndSignersData(tokenPayload);

        if (!documentPackageSigner || !user) {
            return res.status(404).send({ status: false, message: 'No se encontraron los datos del paquete o del usuario.' });
        }

        const signUrl = await service.uploadSignToS3(
            documentPackageSigner.company_id,
            documentPackageSigner.id,
            req.body.sign
        );

        const fieldsValues = req.body.fieldsValues;

        await updateSignerStatusAndLog(tokenPayload, req, signUrl);

        const htmlDocsPdf = await processDocuments(documentPackageSigner, user, req.body.sign, req.ip, fieldsValues);

        const signedAt = new Date();
        const options = { timeZone: 'America/Bogota' };

        const date = signedAt.toLocaleDateString('es-CO', options);
        const time = signedAt.toLocaleTimeString('es-CO', options);

        service.sendAgradecimientoSolicitudFirma(
            user.email,
            documentPackageSigner.company.avatar,
            `${user.firstname} ${user.lastname}`,
            documentPackageSigner.company.fiscal_name,
            date,
            time,
            documentPackageSigner.company.email
        );

        await checkAndFinalizePackage(tokenPayload, documentPackageSigner, date, time, htmlDocsPdf);

        await triggerNextSigner(documentPackageSigner, signers, user, date, time);

        res.status(200).send({
            status: true,
            message: "Solicitud de firma procesada exitosamente.",
        });


    } catch (err) {
        console.log(err)
        res.status(401).send({
            status: false,
            message: `Error al guardar en la base de datos: ${err} `,
        });
    }
}

async function updateHashDocumentSigned(documentPackageSignerId) {
    try {
        const documentPackageSigner = await db.document_packages_signers.findFirst({
            where: {
                id: parseInt(documentPackageSignerId),
            },

            select: {
                id: true,
                signers: {
                    select: {
                       sign: true
                    },

                },
                documents: {
                    select: {
                        id: true,
                        name: true,
                        s3_key: true,

                    }
                },
            }

        });

        const signers = documentPackageSigner.signers;
        const documents = documentPackageSigner.documents;

        const allSignatures = signers.map(signer => signer.sign).join('-');

        for (const document of documents) {
            const documentString = `${document.id}-${allSignatures}-${documentPackageSignerId}`;

            const documentHash = crypto.createHash('sha256').update(documentString).digest('hex');

            await db.document_packages_signers_details_values.updateMany({
                where: {
                    id: document.id,
                    document_package_signer_id: parseInt(documentPackageSignerId),
                },
                data: {
                    document_hash: documentHash,
                },
            });

        }

        return true;

    } catch (error) {
        console.error("Error al actualizar el estado de firmado:", error);
        return false;
    }

}

async function updateContentWithFields(
    modified_content,
    fieldsValues
) {

    try {
        if (modified_content) {
            let content = modified_content;

            for (const fieldValue of fieldsValues) {
                const { name, value } = fieldValue;

                const fieldRegex = new RegExp("\\$\\[\\[" + name + "\\]\\]", "g");

                content = content.replace(fieldRegex, value !== undefined && value !== null ? value : `$[[${name}]]`);
            }

            return { success: true, updatedContent: content };
        } else {
            throw new Error("Document package detail not found");
        }
    } catch (err) {
        console.error("Error updating content:", err);
        return { success: false, error: err.message };
    }
}

