async function resendSignRequest (req, res) {

    try {

        const request = await db.document_packages_signers.findFirst({
            where: {
                id: parseInt(req.body.id),
            },
            include: {
                document_packages_header: {
                    select: {
                        order: true,
                        name: true,
                    }
                },
                signers: {
                    select: {
                        user_id: true,
                        status: true,
                        token: true,
                        order: true,
                    },
                    orderBy: { order: 'asc' }
                },
                company: {
                    select: {
                        id: true,
                        avatar: true,
                        fiscal_name: true,
                        email: true,
                        advanced_settings: {
                            select: {
                                email_message: true,
                            }
                        },
                        parent: {
                            select: {
                                id: true,
                                advanced_settings: { select: { email_message: true } }
                            }
                        }
                    },

                }
            }
        });

        let advancedSettings =
            request.company.parent?.advanced_settings?.length > 0
                ? request.company.parent.advanced_settings
                : request.company.advanced_settings;


        let date = request.expires_in_days.toLocaleDateString('es-ES');
        let time = request.expires_in_days.toLocaleTimeString(); 

        const userIds = request.signers.map(signer => signer.user_id);

        const users = await db.users.findMany({
            where: {
                id: {
                    in: userIds
                }
            }
        });

        let company = request.company;

        let message = "";
        let status;

        if (request.status === "send" || request.status === "rejected") {

            const sortedSigners = [...request.signers].sort((a, b) => a.order - b.order);

            if (request.document_packages_header.order == 1) {
                for (let i = 0; i < sortedSigners.length; i++) {
                    const signer = sortedSigners[i];

                    if (signer.status === "accepted") continue;

                    const previousUnsigned = sortedSigners
                        .slice(0, i)
                        .some(prev => prev.status !== "accepted");

                    if (previousUnsigned) break;

                    const user = users.find(u => u.id === signer.user_id);
                    const _url = process.env.ENV_URL + signer.token;

                    if (signer.status === "send" || signer.status === "rejected") {
                        await service.sendSolicitudFirma(
                            user.email,
                            company.avatar,
                            `${user.firstname} ${user.lastname}`,
                            company.fiscal_name,
                            company.fiscal_name,
                            company.fiscal_name,
                            date,
                            time,
                            _url,
                            company.email,
                            request.document_packages_header.name,
                            advancedSettings[0].email_message || "",
                            user.id,
                            request.id,
                            company.id
                        );
                        status = true;
                        break; 
                    }
                }
            } else {
                for (const signer of sortedSigners) {
                    if (signer.status === "send" || signer.status === "rejected") {
                        const user = users.find(u => u.id === signer.user_id);
                        const _url = process.env.ENV_URL + signer.token;

                        await service.sendSolicitudFirma(
                            user.email,
                            company.avatar,
                            `${user.firstname} ${user.lastname}`,
                            company.fiscal_name,
                            company.fiscal_name,
                            company.fiscal_name,
                            date,
                            time,
                            _url,
                            company.email,
                            request.document_packages_header.name,
                            company.advanced_settings[0].email_message || "",
                            user.id,
                            request.id,
                            company.id
                        );
                        status = true;
                    }
                }
            }

