        res.status(200).send({
            status: true,
            message:  "Solicitud anulada correctamente",
        });


    } catch (error) {
        console.log(error)
        res.status(400).send({

            message: error,
        });
    }
}

async function getUserSigners(req, res) {
    try {

        const id = parseInt(req.body.id);

        const document_package_signer = await db.document_packages_signers.findFirst({
            where: {
                id: id,
            },
            select: {
                expires_in_days: true,
            }
        });

        const signers = await db.document_signers.findMany({
            where: {
                document_package_signer_id: id
            },
            select: {
                id: true,
                document_package_signer_id: true,
                user_id: true,
                order: true,
                status: true,
                expires_in_days: true,
                signed_at: true,
                updated_at: true,
                created_at: true,
                users: {
                    select: {
                        firstname: true,
                        lastname: true,
                        email: true
                    }
                }
            },

        });

        let _data = [];

        const data = signers;

        for (let i = 0; i < data.length; i++) {

            let _status = "";
            switch (data[i].status.trim()) {
                case "send":
                    _status = "0";
                    break;
                case "accepted":
                    _status = "1";
                    break;
                case "rejected":
                    _status = "2";
                    break;
                case "canceled":
                    _status = "3";
                    break;
                case "expired":
                    _status = "4";
                    break;
                case "blocked":
                    _status = "5";                

            }

            _data.push({
                id: data[i].id,
                document_package_signer_id: data[i].document_package_signer_id,
                user_id: data[i].user_id,
                order: data[i].order,
                expires_in_days: data[i].expires_in_days ? data[i].expires_in_days : document_package_signer.expires_in_days,
                created_at: data[i].created_at,
                updated_at: data[i].signed_at ?  data[i].signed_at : data[i].updated_at,
                status: _status,
                users: {
                    name: data[i].users.firstname + " " + data[i].users.lastname,
                    email: data[i].users.email,
                },

            });
        }


        res.status(200).send({
            status: true,
            data: _data
        });

    } catch (error) {
        console.log(error)
        res.status(400).send({
            status: false,
            message: error,
        });
    }
}

