async function getAttemptLogs(req, res) {
    try {
        const { filters = {}, itemsPerPage = 10, page = 1, company_id, role_id } = req.body;
        const skip = (page - 1) * itemsPerPage;

        const where = {};
        if (req.body.type) {
            where.type = req.body.type;
        }
        if (parseInt(role_id) !== 20) {
            where.company_id = parseInt(company_id);
        }

        if (filters.created_at) {
            const startDate = new Date(filters.created_at);
            startDate.setUTCHours(5, 0, 0, 0);
            const endDate = new Date(startDate);
            endDate.setDate(startDate.getDate() + 1);
            where.created_at = { gte: startDate, lt: endDate };
        }
        if (filters.signer) {
            where.user = {
                OR: [
                    { firstname: { contains: filters.signer } },
                    { lastname: { contains: filters.signer} },
                ]
            };
        }
        if (filters.document_package_signer_id) {
            where.document_package_signer_id =  { in: filters.document_package_signer_id ? [parseInt(filters.document_package_signer_id)] : [] };
        }
        if (filters.document_name) {
            where.document = {
                name: { contains: filters.document_name }
            };
        }
        if (filters.company_name) {
            where.company = {
                company_name: { contains: filters.company_name }
            };
        }

        const groupedLogs = await db.attempts_log.groupBy({
            by: ['user_id', 'document_package_signer_id', 'company_id'],
            where,
            _count: {
                id: true, 
            },
            orderBy: {
                user_id: 'asc',
            },
            skip,
            take: itemsPerPage,
        });

        const total = await db.attempts_log.count({ where });

        const _data = await Promise.all(groupedLogs.map(async (group) => {
            const firstLog = await db.attempts_log.findFirst({
                where: {
                    user_id: group.user_id,
                    document_package_signer_id: group.document_package_signer_id,
                    company_id: group.company_id,
                },
                include: {
                    user: true,
                    company: true,
                    document: {
                        include: {
                            document_packages_signer: {
                                include: {
                                    document_packages_header: true
                                }
                            }
                        }
                    }
                }
            });

            return {
                user_id: group.user_id,
                document_package_signer_id: group.document_package_signer_id,
                company_name: firstLog.company.company_name,
                document_package_header_name: firstLog.document.document_packages_signer.document_packages_header?.name,
                user_name: `${firstLog.user.firstname} ${firstLog.user.lastname}`,
                attempt_date: firstLog.created_at,
                attempts_count: group._count.id,
                email: firstLog.user.email,
                document_name: firstLog.document.name,
            };
        }));

        res.status(200).send({
            status: true,
            total,
            current_page: page,
            total_pages: Math.ceil(total / itemsPerPage),
            data: _data,
        });

    } catch (error) {
        console.error("Error en getAttemptLogs:", error);
        res.status(500).send({ status: false, message: error.message });
    }
}

async function exportAttemptLogs(req, res) {
