async function uploadSignImages(req, res) {

    const uploadImage = async (image) => {
        const imageBuffer = Buffer.from(image.data.replace(/^data:image\/\w+;base64,/, ""), 'base64');
        const hash = service.generateHash(imageBuffer);

        const docPackageSignerId = parseInt(req.body.document_package_signer_id);
        const userId = parseInt(req.body.user_id);

        try {

            await db.document_sign_images.deleteMany({
                where: {
                    document_package_signer_id: docPackageSignerId,
                    user_id: userId,
                    type: image.type,
                }
            });

            const existingImage = await db.document_sign_images.findFirst({
                where: { 
                    hash: hash,
                    document_package_signer_id: parseInt(req.body.document_package_signer_id),

                 }
            });


            if (existingImage) {
                console.log("Imagen con el mismo hash ya existe. No se guardará.");
                return;
            }

            const uploadParams = {
                Bucket: process.env.S3_BUCKET,
                Key: `signature_request/images/${hash}.png`,
                Body: imageBuffer,
                ContentType: 'image/png',
            };

            const upload = new Upload({
                client: s3Client,
                params: uploadParams
            });

            const data = await upload.done();

            const url = data.Location;
            await db.document_sign_images.create({
                data: {
                    document_package_signer_id: parseInt(req.body.document_package_signer_id),
                    user_id: parseInt(req.body.user_id),
                    hash: hash,
                    type: image.type,
                    image_url: url,
                    created_at: image.date,
                }
            });

        } catch (err) {
            console.log("Error uploading image:", err);
            throw err;
        }
    };


    try {
        await Promise.all(req.body.images.map(image => uploadImage(image)));
        res.status(200).send({
            status: true,
            message: "Imágenes subidas correctamente.",
        });
    } catch (error) {
        console.log("Error in uploading images:", error);
        res.status(500).send({
            status: false,
            message: "Error al subir imágenes.",
        });
    }
};

