        const document_package_signer = await db.document_packages_signers.findFirst({
            where: { liquidation_id: liquidation_id },
            include: {
                company: true,
                signers: {
                    select: {
                        id: true,
                        user_id: true,
                        status: true,
                    },
                },
            },
        });


        if (document_package_signer.company.api_key != api_key) {
            return res.status(404).send({
                status: false,
                message: "Verifique el campo api_key",
            });        
        }


        if (!document_package_signer) {
            return res.status(404).send({
                status: false,
                message: "Documento no encontrado",
            });
        }

        if (document_package_signer.status === "blocked" || document_package_signer.status === "canceled" || document_package_signer.status === "accepted") {
            return res.status(400).send({
                status: false,
                message: "La solicitud ya está bloqueada o anulada, no se puede modificar",
            });
        }

        const hasAcceptedSigner = document_package_signer.signers.some(signer => signer.status === "accepted");

        if (hasAcceptedSigner) {
            return res.status(400).send({
                status: false,
                message: "No se puede bloquear la solicitud porque uno o más firmantes ya la han firmado.",
            });
        }

        await db.document_packages_signers.update({
            where: { id: parseInt(document_package_signer.id) },
            data: { status: "blocked" },
        });

        await db.document_signers.updateMany({
            where: { document_package_signer_id: parseInt(document_package_signer.id) },
            data: { status: "blocked" },
        });

        return res.status(200).send({
            status: true,
            message: "Solicitud bloqueada correctamente",
        });
    } catch (error) {
        console.error(error);
        return res.status(500).send({
            status: false,
            message: "Error al bloquear la solicitud",
            error: error.message,
        });
    }
}

async function revokeSignRequest(req, res) {
    try {
        const { id, process_type, api_key } = req.body;

        let liquidation_id = null;
        let contract_number = null;

        if (parseInt(process_type) === 1) {
            liquidation_id = id;
        } else {
            contract_number = id;
        }

        const whereClause = process_type === 1
            ? { liquidation_id: liquidation_id }
            : { contract_number: contract_number };

        const document_package_signer = await db.document_packages_signers.findFirst({
            where: whereClause,
            select: {
                id: true,
                company: true,
                signers: {
                    select: {
                        id: true,
                        user_id: true,
                        status: true,
                        order: true,
                        users: {
                            select: {
                                firstname: true,
                                lastname: true,
                                email: true
                            }
                        }
                    },
                },
            },
        });

        if (!document_package_signer) {
            return res.status(404).send({
                status: false,
                message: "Solicitud no encontrada",
            });
        }
        if (document_package_signer.company.api_key != api_key) {
            return res.status(404).send({
                status: false,
                message: "Verifique el campo api_key",
            });        
        }

        if (document_package_signer.status === "canceled" ) {
            return res.status(400).send({
                status: false,
                message: "La solicitud ya está anulada, no se puede modificar",
            });
        }


        await db.document_packages_signers.update({
            where: { id: parseInt(document_package_signer.id) },
            data: { status: "canceled" },
        });

        await db.document_signers.updateMany({
            where: { document_package_signer_id: parseInt(document_package_signer.id) },
            data: { status: "canceled" },
        });

        const user = document_package_signer.signers.find((user) => user.order === 2);


        await service.sendCancelSignRequestNotification(
            user.users.email,
            document_package_signer.company.avatar,
            user.users.firstname + " " + user.users.lastname,
            document_package_signer.company.company_name,
            document_package_signer.company.email,
        );

        return res.status(200).send({
            status: true,
            message: "Solicitud anulada correctamente",
        });

    } catch (error) {
        console.error(error);
        return res.status(500).send({
            status: false,
            message: "Error al revocar la solicitud",
            error: error.message,
        });
    }
}

async function getSignRequestLogs(req, res) {
